const b = ($input.first().json.body) || $input.first().json || {};
const type = (b.type || 'web').toString();
const email = (b.email || '').toString().trim();
if (!email) return [];
let notes;
if (type === 'contact-form') notes = 'Website contact form: ' + (b.message || '(no message)');
else if (type === 'pricing-guide') notes = 'Downloaded the pricing guide (region: ' + (b.country || 'ZA') + ')';
else if (type === 'roi') notes = 'Used the ROI calculator (' + (b.mode || 'savings') + ' mode)';
else notes = 'Website enquiry';
return [{ json: {
  email,
  first_name: (b.firstName || '').toString().trim(),
  last_name:  (b.lastName  || '').toString().trim(),
  phone:      (b.phone     || '').toString().trim(),
  country:    (b.country   || '').toString().trim(),
  industry:   (b.business  || '').toString().trim(),
  how_heard:  (b.hearAbout || 'Website').toString().trim(),
  notes,
  source: type,
  lead_status: 'lead'
}}];

