const parts = ($json.content && $json.content.parts) || [];
const raw = String((parts[0] && parts[0].text) || '').trim();
let category = 'lead';
try {
  const cleaned = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const parsed = JSON.parse(cleaned);
  if (parsed && (parsed.category === 'lead' || parsed.category === 'faq')) category = parsed.category;
} catch (e) {}
return [{ json: { output: { category } } }];
